import React from "react";
import QuotePage from "./QuotePage"; // reuse your existing quote form
import LoginPage from "./LoginPage";
import logo from "../assets/logo.png"; // update to your actual logo path

const HomePage = ({ onLogin }) => {
  return (
    <div className="home-page">
      {/* Header Section */}
      <header className="text-center p-6 bg-light shadow-sm">
        <img
          src={logo}
          alt="Doyle's Coffee & Break Room Services"
          style={{ width: "150px", marginBottom: "10px" }}
        />
        <h1 className="fw-bold">Doyle's Coffee & Break Room Services</h1>
        <p className="text-muted">
          Premium coffee and break room solutions for your workplace.
        </p>
      </header>

      {/* About Section */}
      <section className="container my-5">
        <h2 className="text-center mb-3">About Us</h2>
        <p className="text-center">
          At Doyle’s Coffee & Break Room Services, we provide everything your
          team needs to stay energized — from coffee and snacks to equipment and
          maintenance. Reliable service, quality products, and friendly support
          are what set us apart.
        </p>
      </section>

      {/* Quote Request Section */}
      <section className="container my-5">
        <h2 className="text-center mb-4">Request a Quote</h2>
        <QuotePage />
      </section>

      {/* Login Section */}
      <section className="container my-5">
        <h2 className="text-center mb-4">Admin / Customer Login</h2>
        <LoginPage onLogin={onLogin} />
      </section>
    </div>
  );
};

export default HomePage;
